questions.solutionCode:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract Counter {
    uint256 private _count;

    function increment() external {
        _count += 1;
    }

    function count() external view returns (uint256) {
        return _count;
    }
}
